import{_ as a,o as i,c as t,a6 as s}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"插件开发概览","description":"","frontmatter":{"title":"插件开发概览","docId":"developer.plugins.index","translationKey":"developer.plugins.index","locale":"zh","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"690689449dfe463405cff0ea6b3a33979249bbe68c598ee7e8ca862eedd704dc","translationRevision":"8a1d746c513fdb6ecfa6624e54dd3807ed5f6b7c123fa6eaea6cca530051e49c","order":240},"headers":[],"relativePath":"zh/developer/plugins/index.md","filePath":"zh/developer/plugins/index.md","lastUpdated":1794611623000}'),l={name:"zh/developer/plugins/index.md"};function n(r,e,o,d,p,h){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="plugin-development-overview" tabindex="-1">插件开发概览 <a class="header-anchor" href="#plugin-development-overview" aria-label="Permalink to &quot;插件开发概览 {#plugin-development-overview}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>选择能够满足集成需要的最小插件边界。TikTools 从内置、用户及开发根目录发现运行时包；添加包不需要把特定插件重新编译进宿主。测试效果前，使用匹配的 devkit/SDK 和私有开发配置。</p><h2 id="follow-the-authoring-path" tabindex="-1">按开发路径推进 <a class="header-anchor" href="#follow-the-authoring-path" aria-label="Permalink to &quot;按开发路径推进 {#follow-the-authoring-path}&quot;">​</a></h2><ol><li>从<a href="./quickstart.html">快速入门</a>开始，创建、验证并构建隔离的包。</li><li>根据原生依赖和信任选择<a href="./runtimes.html">运行时</a>，不要只看文件扩展名。</li><li>声明<a href="./permissions-ui.html">权限与 UI</a>，让宿主可以审查效果并渲染配置。</li><li>通过<a href="./packaging-registry.html">打包与注册表</a>处理完整性、发布者信任及更新策略。</li></ol><p>底层 Rust 权威实现是 <code>crates/tiktools-plugin-api</code>，负责清单验证、协议和 UI 契约。<code>crates/tiktools-plugin-sdk</code> 提供 Rust 作者接口；<code>packages/plugin-sdk</code> 包含 TypeScript 辅助函数及<a href="https://github.com/nglmercer/TikTools-app/blob/remake/packages/plugin-sdk/plugin.schema.json" target="_blank" rel="noreferrer">编辑器 schema</a>。运行时加载属于 <code>crates/tiktools-plugin-loader</code>，不属于前端。</p><h2 id="understand-contributions" tabindex="-1">理解插件贡献类型 <a class="header-anchor" href="#understand-contributions" aria-label="Permalink to &quot;理解插件贡献类型 {#understand-contributions}&quot;">​</a></h2><p>操作通过类型化结果请求副作用。事件源发布触发器；观察者通过有界投递接收稳定的 <code>{topic,data}</code> 领域封装。处理器在 <code>event.intel</code> 下添加无副作用的证据，并具备截止时间、确定性合并和健康隔离。声明式设置/操作让宿主渲染常规配置。自定义编译页面在自己的框架/窗口中使用受限插件代理，其脚本绝不会成为主 Vue 运行时的一部分。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>这些是针对宿主/SDK 的检查，不是对任意外部包的验证。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>native、process、declarative 和基于 QuickJS 的 <code>napi-vm</code> 路径均已实现。WASM 是可选运行时槽位，常规构建中没有启用通用引擎。示例集成位于独立的 <a href="https://github.com/nglmercer/plugins-example-tiktools" target="_blank" rel="noreferrer">plugins-example-tiktools 仓库</a>；旧文档中的源码名称不代表它们是随产品捆绑的功能。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>发现失败时，检查清单兼容性、根目录优先级、目标及入口路径。意图被拒绝时，检查声明和获授的能力，不要绕过宿主。启动结果不确定时，必须先协调确认再替换。原生/进程边界仍受操作系统级信任限制；运行时名称本身不能证明存在沙箱。</p>`,14)])])}const k=a(l,[["render",n]]);export{u as __pageData,k as default};
